using System;using System.IO;using System.Linq;using UnityEngine;using EternalSteam.OpenWorld;using TMPro;using Newtonsoft.Json.Linq;
public static class InspectHud07{public static string Main(){var h=UnityEngine.Object.FindFirstObjectByType<CanvasWorldHud>();var report=new JObject{{"texts",new JArray(h.Texts.Select(t=>new JObject{{"id",t.Id},{"name",t.View.name},{"parent",t.View.transform.parent.name},{"font",t.View.fontSize},{"rect",t.View.rectTransform.rect.ToString()},{"pos",t.View.rectTransform.anchoredPosition.ToString()}}))},{"objective",new JArray(h.Layout.FirstLoopObjective.GetComponentsInChildren<RectTransform>(true).Select(r=>new JObject{{"name",r.name},{"rect",r.rect.ToString()},{"pos",r.anchoredPosition.ToString()},{"text",r.GetComponent<TMP_Text>()?.text}}))},{"floating",new JArray(h.Layout.FloatingPanels.Select(p=>new JObject{{"name",p.name},{"parent",p.parent.name},{"parentRect",((RectTransform)p.parent).rect.ToString()},{"size",p.rect.ToString()},{"scale",p.lossyScale.ToString()}}))}};File.WriteAllText("Docs/Measurements/2026-10-02-hud-07/inspection.json",report.ToString());return report.ToString();}}
